#include <stdio.h>

int fib(int n) {
    if (n <= 1) {
        return n;
    }
    return fib(n - 1) + fib(n - 2);
}

int power(int base, int exp) {
    if (exp == 0) {
        return 1;
    }
    return base * power(base, exp - 1);
}

int sumDigits(int n) {
    if (n == 0) {
        return 0;
    }
    return (n % 10) + sumDigits(n / 10);
}

int main(void) {
    printf("fib(7) = %d\n", fib(7));
    printf("2^10 = %d\n", power(2, 10));
    printf("Sum of digits of 4031 = %d\n", sumDigits(4031));
    return 0;
}

