bug.fixed:
#include <stdio.h>

long long fib(int n) {
    long long a = 0, b = 1;
    for (int i = 0; i < n; i++) {
        long long next = a + b;
        a = b;
        b = next;
    }
    return a;
}

int main(void) {
    printf("fib(40) = %lld\n", fib(40));
    return 0;
}

